# Surah Yusuf (chapter 12) — part 9: ayat 81-90 (IDs 1677-1686)
SURAH = 12

ENTRIES = {
1677: (
"واپس — جائیں — اپنے باپ — کے پاس — اور — کہو — اے — ہمارے ابا — بے شک — آپ کے بیٹے — نے — چوری کی — اور — ہم نے گواہی — دی — صرف اس چیز کی — جو ہم نے جانی — اور — ہم — غیب — کی خبر — رکھنے والے نہیں",
"""۱۔ بھائی — واپس جا کر باپ — سے جھوٹا واقعہ بیان کرنے کی تدبیر — کرتے ہیں۔
۲۔ ’’ارْجِعُوا إِلَىٰ أَبِيكُمْ فَقُولُوا يَا أَبَانَا إِنَّ ابْنَكَ سَرَقَ وَمَا شَهِدْنَا إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَافِظِينَ‘‘ — واپس — جائیں — اپنے باپ — کے پاس — اور — کہو — اے — ہمارے ابا — بے شک — آپ کے بیٹے — نے — چوری کی — اور — ہم نے گواہی — دی — صرف اس چیز کی — جو ہم نے جانی — اور — ہم — غیب — کی خبر — رکھنے والے نہیں — یعنی واپس — جاؤ — اپنے باپ — کے پاس — اور کہو — اے — ہمارے — ابا — بے شک — آپ کے بیٹے نے — چوری کی — اور ہم نے — گواہی دی — صرف — اس چیز کی جو ہم نے دیکھی — اور ہم — غیب — کی — خبر — رکھنے والے — نہیں۔
۳۔ عملی سبق: پوری حقیقت — کہنا — ہی — نجات کا راستہ — ہے۔"""
),
1678: (
"اور — پوچھ — لیجیے — بستی — سے جس — میں — ہم — تھے — اور — کاروان — سے — جس میں — ہم — آئے — اور — بے شک — ہم — سچے ہیں",
"""۱۔ بھائی — گواہی — کے لیے آمادگی — دکھاتے ہیں۔
۲۔ ’’وَاسْأَلِ الْقَرْيَۃَ الَّتِي كُنَّا فِيهَا وَالْعِيرَ الَّتِي أَقْبَلْنَا فِيهَا وَإِنَّا لَصَادِقُونَ‘‘ — اور — پوچھ — لیجیے — بستی — سے جس — میں — ہم — تھے — اور — کاروان — سے — جس میں — ہم — آئے — اور — بے شک — ہم — سچے ہیں — یعنی اور — پوچھ — لیجیے — اس — بستی — سے جس میں — ہم — تھے — اور — اس — کاروان — سے جس میں — ہم آئے — اور — بیشک — ہم — سچے ہیں۔
۳۔ عملی سبق: سچ — کا — ثبوت — ہمیشہ — دیا — جا سکتا ہے۔"""
),
1679: (
"یعقوبؑ نے — کہا — بلکہ — تمہارے نفسوں نے — تمہارے لیے — ایک — بات — کو — آسان بنایا — پس — صبر — جمیل — ہے — امید ہے کہ اللہ — انہیں — سب کو — میرے پاس — لا دے گا — بے شک — وہ — علیم حکیم — ہے",
"""۱۔ یعقوبؑ — تقدیر پر یقین — صبر جمیل — کا فیصلہ کرتے ہیں۔
۲۔ ’’قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ عَسَى اللَّهُ أَن يَأْتِيَنِي بِهِمْ جَمِيعًا إِنَّهُ هُوَ الْعَلِيمُ الْحَكِيمُ‘‘ — یعقوبؑ نے — کہا — بلکہ — تمہارے نفسوں نے — تمہارے لیے — ایک — بات — کو — آسان بنایا — پس — صبر — جمیل — ہے — امید ہے کہ اللہ — انہیں — سب کو — میرے پاس — لا دے گا — بے شک — وہ — علیم حکیم — ہے — یعنی یعقوبؑ نے کہا — بلکہ تمہارے نفسوں نے — تمہارے لیے — ایک بات — کو — آسان بنایا — پس — صبر جمیل — ہے — امیدوار ہوں کہ اللہ — انہیں — سب کو — میرے پاس — لا دے گا — بے شک — وہ — علیم حکیم — ہے۔
۳۔ عملی سبق: جب حالات — نا امید — ہوں؛ صبر — پر استقامت — رکھیے۔"""
),
1680: (
"اور — یعقوبؑ — نے ان — سے — منہ — موڑ لیا — اور — کہا — ہائے افسوس — یوسفؑ — پر — اور — ان کی آنکھیں — غم سے — سفید — ہو گئیں — اور — وہ — غم — کو — پی جاتا — تھا",
"""۱۔ یعقوبؑ — کا — غم شدید — فرزقیر — ہوتی ہے۔
۲۔ ’’وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَا أَسَفَىٰ عَلَىٰ يُوسُفَ وَابْيَضَّتْ عَيْنَاهُ مِنَ الْحُزْنِ فَهُوَ كَظِيمٌ‘‘ — اور — یعقوبؑ — نے ان — سے — منہ — موڑ لیا — اور — کہا — ہائے افسوس — یوسفؑ — پر — اور — ان کی آنکھیں — غم سے — سفید — ہو گئیں — اور — وہ — غم — کو — پی جاتا — تھا — یعنی یعقوبؑ نے — ان — سے — منہ — موڑ لیا — اور کہا — ہائے — افسوس — یوسفؑ پر — اور ان کی آنکھیں — غم — سے — سفید — ہو گئیں — اور — وہ غم — کو — پی — جاتا تھا۔
۳۔ عملی سبق: عظیم غم — میں — بھی اللہ — پر — صبر — رکھیے۔"""
),
1681: (
"انہوں نے کہا — اللہ کی قسم — آپ — یوسفؑ — کی یاد میں — ہمیشہ — اذیت — میں رہیں گے — یہاں تک کہ — آپ — چُوکے — جائیں — یا مر جائیں",
"""۱۔ بیٹے — یعقوبؑ — کی غیرمعمولی تنہائی کا — اظہار — کرتے ہیں۔
۲۔ ’’قَالُوا تَاللَّهِ تَفْتَأُ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ الْهَالِكِينَ‘‘ — انہوں نے کہا — اللہ کی قسم — آپ — یوسفؑ — کی یاد میں — ہمیشہ — اذیت — میں رہیں گے — یہاں تک کہ — آپ — چُوکے — جائیں — یا مر جائیں — یعنی انہوں نے کہا — اللہ کی قسم — آپ — یوسفؑ — کی یاد میں — ہمیشہ — اذیت — میں رہیں گے — یہاں تک کہ — آپ — کمزور — پڑ جائیں — یا — مر — جائیں۔
۳۔ عملی سبق: والدین کے دکھ — کو — سمجھنا — اور عزت دینا — اولاد کا فریضہ ہے۔"""
),
1682: (
"انہوں نے کہا — میں — اپنی — شدت اور غم — اللہ — سے — شکایت — کرتا ہوں — اور — میں — اللہ — سے — وہ جانتا — ہوں — جو تم نہیں — جانتے",
"""۱۔ یعقوبؑ — اللہ — سے شکایت کرتے ہیں — دوسروں سے نہیں۔
۲۔ ’’قَالَ إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ وَأَعْلَمُ مِنَ اللَّهِ مَا لَا تَعْلَمُونَ‘‘ — انہوں نے کہا — میں — اپنی — شدت اور غم — اللہ — سے — شکایت — کرتا ہوں — اور — میں — اللہ — سے — وہ جانتا — ہوں — جو تم نہیں — جانتے — یعنی یعقوبؑ نے کہا — میں — اپنی — شدت — اور غم — اللہ — کے پاس — شکایت — کرتا ہوں — اور — میں — اللہ — سے وہ — جانتا ہوں — جو تم — نہیں — جانتے۔
۳۔ عملی سبق: شکایت — اللہ — سے — ہونی — چاہیے؛ بھلائی کی توقع — اللہ — سے — ہے۔"""
),
1683: (
"اے میرے بیٹو — جاؤ — اور — یوسفؑ — اور — اس — کے بھائی — کی کھوج — کرو — اور — اللہ کی رحمت سے مایوس — نہ ہو — بے شک — اللہ کی رحمت — سے مایوس — نہیں ہوتا — مگر — کافر — لوگ",
"""۱۔ یعقوبؑ — بیٹوں کو مصر واپس — بھیجتے ہیں؛ اللہ کی رحمت — سے مایوس — نہ ہونے کی تاکید۔
۲۔ ’’يَا بَنِيَّ اذْهَبُوا فَتَحَسَّسُوا مِن يُوسُفَ وَأَخِيهِ وَلَا تَيْئَسُوا مِن رَّوْحِ اللَّهِ إِنَّهُ لَا يَيْئَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ‘‘ — اے میرے بیٹو — جاؤ — اور — یوسفؑ — اور — اس — کے بھائی — کی کھوج — کرو — اور — اللہ کی رحمت سے مایوس — نہ ہو — بے شک — اللہ کی رحمت — سے مایوس — نہیں ہوتا — مگر — کافر — لوگ — یعنی یعقوبؑ نے کہا — اے — میرے بیٹو — جاؤ — اور — یوسفؑ — اور اس — کے بھائی — کی کھوج — کرو — اور — اللہ — کی رحمت — سے مایوس — نہ ہو — بے شک — اللہ — کی رحمت — سے مایوس — نہیں ہوتا — مگر — کافر — لوگ۔
۳۔ عملی سبق: اللہ کی رحمت — سے ناامیدی — کفر — کی — علامت ہے۔"""
),
1684: (
"پس — جب — وہ — اس کے پاس — داخل ہوئے — انہوں نے — کہا — اے — عزیز — ہم — پر اور ہمارے گھر والوں پر — تکلیف — آ گئی ہے — اور ہم — ایک معمولی — پونجی — لے کر — آئے ہیں — پس ہمیں — پیمانہ — پورا — دے دیجیے — اور ہم پر صدقہ کیجئے — بے شک — اللہ — صدقہ کرنے والوں — کو — اجر دیتا ہے",
"""۱۔ قحط — کی وجہ سے — بھائی — دوبارہ مصر — پہنچے؛ افسردگی — اور عجز کا اظہار۔
۲۔ ’’فَلَمَّا دَخَلُوا عَلَيْهِ قَالُوا يَا أَيُّهَا الْعَزِيزُ مَسَّنَا وَأَهْلَنَا الضُّرُّ وَجِئْنَا بِبِضَاعَۃٍ مُّزْجَاۃٍ فَأَوْفِ لَنَا الْكَيْلَ وَتَصَدَّقْ عَلَيْنَا إِنَّ اللَّهَ يَجْزِي الْمُتَصَدِّقِينَ‘‘ — پس — جب — وہ — اس کے پاس — داخل ہوئے — انہوں نے — کہا — اے — عزیز — ہم — پر اور ہمارے گھر والوں پر — تکلیف — آ گئی ہے — اور ہم — ایک معمولی — پونجی — لے کر — آئے ہیں — پس ہمیں — پیمانہ — پورا — دے دیجیے — اور ہم پر صدقہ کیجئے — بے شک — اللہ — صدقہ کرنے والوں — کو — اجر دیتا ہے — یعنی پس جب — وہ اس کے پاس — داخل — ہوئے — انہوں نے کہا — اے — عزیز — ہم — پر — اور ہمارے اہل — پر — تکلیف — آ گئی ہے — اور ہم — ایک — معمولی — پونجی — لے کر آئے ہیں — پس ہمیں — پیمانہ — پورا — دے دیجیے — اور ہم پر — صدقہ کیجیے — بے شک — اللہ — صدقہ کرنے والوں کو — اجر — دیتا ہے۔
۳۔ عملی سبق: ضرورت — ترک — نفس — مانگتی — ہے؛ دوسروں سے مدد مانگنا مباح ہے۔"""
),
1685: (
"یوسفؑ — نے کہا — کیا — تم جانتے ہو — تم نے یوسفؑ اور اس کے بھائی کے ساتھ — کیا — کیا — جب — تم لوگ — نادان تھے",
"""۱۔ یوسفؑ — بھائیوں — کو — پرانا — ظلم — یاد دلاتے ہیں۔
۲۔ ’’قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَاهِلُونَ‘‘ — یوسفؑ — نے کہا — کیا — تم جانتے ہو — تم نے یوسفؑ اور اس کے بھائی کے ساتھ — کیا — کیا — جب — تم لوگ — نادان تھے — یعنی یوسفؑ نے کہا — کیا — تم جانتے ہو — تم نے یوسفؑ اور اس کے بھائی کے ساتھ — کیا — کیا — جب — تم لوگ — نادان تھے۔
۳۔ عملی سبق: سچائی — سامنے آنے پر — خطاکار — کا دل — نرم — ہوتا ہے۔"""
),
1686: (
"انہوں نے کہا — کیا — آپ — یوسفؑ — ہیں — انہوں نے کہا — میں — یوسفؑ ہوں — اور یہ — میرا بھائی ہے — بے شک اللہ نے ہم پر انعام فرمایا — بے شک — جو شخص — تقویٰ کرتا ہے — اور صبر کرتا ہے — بے شک اللہ — نیک لوگوں — کا اجر — ضائع نہیں کرتا",
"""۱۔ بھائی — یوسفؑ کی پہچان کرتے ہیں — یوسفؑ خود کو ظاہر کرتے ہیں۔
۲۔ ’’قَالُوا أَإِنَّكَ لَأَنتَ يُوسُفُ قَالَ أَنَا يُوسُفُ وَهَٰذَا أَخِي قَدْ مَنَّ اللَّهُ عَلَيْنَا إِنَّهُ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ‘‘ — انہوں نے کہا — کیا — آپ — یوسفؑ — ہیں — انہوں نے کہا — میں — یوسفؑ ہوں — اور یہ — میرا بھائی ہے — بے شک اللہ نے ہم پر انعام فرمایا — بے شک — جو شخص — تقویٰ کرتا ہے — اور صبر کرتا ہے — بے شک اللہ — نیک لوگوں — کا اجر — ضائع نہیں کرتا — یعنی انہوں نے کہا — کیا — آپ — یوسفؑ ہیں — انہوں نے کہا — میں — یوسفؑ ہوں — اور — یہ — میرا بھائی ہے — بے شک اللہ نے ہم پر انعام فرمایا — بے شک — جو شخص — تقویٰ کرتا ہے — اور صبر کرتا ہے — بے شک اللہ — نیک لوگوں کا اجر — ضائع نہیں کرتا۔
۳۔ عملی سبق: تقویٰ اور صبر — کے بدلے میں — اللہ — کا انعام — عظیم — ہے۔"""
),
}
